import random
from typing import List

# This generator produces URL-like NUL-terminated strings exercising prefixes:
# - http://
# - cdda://
# - cue://
# and various edge cases (empty, short, long, mixed, non-matching). The fuzzer
# stubs may prepend a prefix conditionally, so we keep bodies meaningful but also
# valid C strings with a terminating NUL.

SCHEMES = [
    "http://",
    "cdda://",
    "cue://",
]

HOST_LABELS = [
    "example", "localhost", "xn--d1acpjx3f", "music", "device", "drive",
    "CD", "Track", "ÄÖÜ", "日本語", "подкаст", "test", "a", "b", "c"
]

TLDS = [
    "com", "org", "net", "local", "invalid", "example", "io", "dev"
]

PATH_SEGS = [
    "", "index.html", "file.flac", "track.cue", "01", "02", "A Space",
    "unicode-ß", "küche", "løve", "数据", "スペース", "çava", "mix.m3u"
]

QUERY_KEYS = [
    "q", "id", "track", "disc", "name", "format", "encoding"
]

QUERY_VALS = [
    "1", "2", "true", "false", "utf-8", "wav", "flac", "äöü", "*",
]

NON_MATCH_PREFIXES = [
    "https://", "ftp://", "file://", "mailto:", "ssh://", "gopher://",
    "http:/", "htt://", "cdd://", "cue:/", "//",
]

ASCII_SAFE = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~"

def _rand_label(r: random.Random, max_parts: int = 3) -> str:
    parts = r.randint(1, max_parts)
    labels = []
    for _ in range(parts):
        if r.random() < 0.7:
            label = r.choice(HOST_LABELS)
        else:
            n = r.randint(1, 10)
            label = ''.join(r.choice(ASCII_SAFE) for _ in range(n))
        labels.append(label)
    host = '.'.join(labels)
    if r.random() < 0.5:
        host += '.' + r.choice(TLDS)
    return host

def _rand_path(r: random.Random, max_depth: int = 4) -> str:
    depth = r.randint(0, max_depth)
    if depth == 0:
        return ''
    segs: List[str] = []
    for _ in range(depth):
        seg = r.choice(PATH_SEGS)
        # Occasionally percent-encode or add spaces to validate downstream handling
        if r.random() < 0.3:
            seg = seg.replace(' ', '%20')
        segs.append(seg)
    return '/' + '/'.join(segs)

def _rand_query(r: random.Random, max_params: int = 3) -> str:
    n = r.randint(0, max_params)
    if n == 0:
        return ''
    pairs = []
    for _ in range(n):
        k = r.choice(QUERY_KEYS)
        v = r.choice(QUERY_VALS)
        if r.random() < 0.2:
            v = v.replace(' ', '+')
        pairs.append(f"{k}={v}")
    return '?' + '&'.join(pairs)

def _rand_fragment(r: random.Random) -> str:
    if r.random() < 0.3:
        n = r.randint(1, 8)
        frag = ''.join(r.choice(ASCII_SAFE) for _ in range(n))
        return '#' + frag
    return ''

def _build_http(r: random.Random) -> str:
    host = _rand_label(r)
    path = _rand_path(r)
    query = _rand_query(r)
    frag = _rand_fragment(r)
    return f"http://{host}{path}{query}{frag}"

def _build_cdda(r: random.Random) -> str:
    # Common shapes: cdda://, cdda://track/N, cdda://dev/sr0, cdda://?dev=/dev/cdrom
    choice = r.randint(0, 3)
    if choice == 0:
        return "cdda://"
    if choice == 1:
        track = r.randint(1, 99)
        return f"cdda://track/{track}"
    if choice == 2:
        dev = r.choice(["sr0", "sr1", "cdrom", "dvd", "mscd0"])  # plausible
        return f"cdda://dev/{dev}"
    devpath = r.choice(["/dev/cdrom", "/dev/sr0", "/dev/rdisk1"])
    return f"cdda://?dev={devpath}"

def _build_cue(r: random.Random) -> str:
    # cue:// followed by a path or filename
    base = r.choice(["/home/user/music/", "/mnt/media/", "", "/tmp/"])
    name = r.choice(["album.cue", "mix.cue", "set.cue", "cuefile.cue", "playlist.cue"])
    extra = _rand_query(r, 2)
    return f"cue://{base}{name}{extra}"

def _build_nonmatch(r: random.Random) -> str:
    # Intentionally not matching the three prefixes
    pfx = r.choice(NON_MATCH_PREFIXES)
    rest = ''
    if r.random() < 0.7:
        rest = _rand_label(r) + _rand_path(r) + _rand_query(r) + _rand_fragment(r)
    return pfx + rest

def _edge_cases(r: random.Random) -> List[str]:
    samples = []
    samples.append("")  # empty string
    samples.append("http://")  # minimal http
    samples.append("cdda://")  # minimal cdda
    samples.append("cue://")   # minimal cue
    samples.append("http://x")  # shortest host
    # Multiple occurrences of suffix to stress ends_with-like behavior elsewhere
    samples.append("http://foo/bar/cue://baz")
    # Long but bounded
    long_host = 'a' * r.randint(60, 120)
    samples.append("http://" + long_host)
    # Non-ASCII content after the scheme
    samples.append("http://exämple.com/füße")
    # Trailing spaces/tabs
    samples.append("http://example.com/path \t\t")
    # Non-matching that looks close
    samples.append("htt://almost")
    return samples

def _choose_candidate(r: random.Random) -> str:
    # Mix deterministic edge cases with random builders
    if r.random() < 0.35:
        return r.choice(_edge_cases(r))
    which = r.randint(0, 5)
    if which == 0:
        return _build_http(r)
    if which == 1:
        return _build_cdda(r)
    if which == 2:
        return _build_cue(r)
    if which == 3:
        return _build_nonmatch(r)
    # Produce a bare body likely to be prefixed by the stub
    body = ''
    if r.random() < 0.6:
        body = _rand_label(r) + _rand_path(r) + _rand_query(r) + _rand_fragment(r)
    return body

def _cap_bytes(b: bytes, limit: int = 4096) -> bytes:
    if len(b) <= limit:
        return b
    return b[:limit-1] + b'\x00'

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    s = _choose_candidate(r)
    # Ensure size constraint and NUL-termination. The fuzz harness may resize to 128,
    # but we keep within reasonable bounds here.
    # Encode as UTF-8; invalid surrogate-like sequences won't appear as we build from literals.
    data = s.encode('utf-8', errors='strict') + b'\x00'
    return _cap_bytes(data, 4096)
